import json
n=30
g=[[0]*n for _ in range(n)]
# Existing frame: rows/cols 1 and 25, spanning the inner 25x25 square.
for c in range(1,26):
    g[1][c]=5; g[25][c]=5
for r in range(1,26):
    g[r][1]=5; g[r][25]=5
# Alternating inward rectangular outlines, leaving a 3x3 zero center.
for r in range(2,25):
  for c in range(2,25):
    layer=min(r-2,24-r,c-2,24-c)
    if layer<10:
      g[r][c]=2 if layer%2==0 else 5
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
